} TNode, *TList;

TList readList(int n) {
    TList head = NULL, tail = NULL;
    for (int i = 0; i < n; i++) {
        TList c = (TList)malloc(sizeof(TNode));
        scanf("%d", &c->val);
        c->next = NULL;
        if (tail) tail->next = c; else head = c;
        tail = c;
    }
    return head;
}

TList reverse(TList l) {
    TList prev = NULL;
    while (l) {
        TList nx = l->next;
        l->next = prev;
        prev = l;
        l = nx;
    }
    return prev;
}

int count(TList l1, TList l2, long long k) {
    int c = 0;
    while (l1 && l2) {
        long long s = (long long)l1->val + l2->val;
        if (s == k) { c++; l1 = l1->next; l2 = l2->next; }
        else if (s < k) l1 = l1->next;
        else l2 = l2->next;
    }
    return c;
}

void freeList(TList l) {
    while (l) { TList p = l->next; free(l); l = p; }
}

