typedef struct {
    char *data;
    int top, cap;
} Stack;

void push(Stack *s, char c) {
    if (s->top == s->cap) {
        s->cap = s->cap ? 2 * s->cap : 16;
        s->data = (char *)realloc(s->data, s->cap);
    }
    s->data[s->top++] = c;
}
int isEmpty(Stack *s) { return s->top == 0; }
char top(Stack *s) { return s->data[s->top - 1]; }
void pop(Stack *s) { s->top--; }

int ok(const char *line) {
    Stack s = {NULL, 0, 0};
    int good = 1;
    for (int i = 0; line[i] && good; i++) {
        char c = line[i];
        if (c == '(' || c == '[' || c == '{') push(&s, c);
        else if (c == ')' || c == ']' || c == '}') {
            char want = c == ')' ? '(' : c == ']' ? '[' : '{';
            if (isEmpty(&s) || top(&s) != want) good = 0;
            else pop(&s);
        }
    }
    if (!isEmpty(&s)) good = 0;
    free(s.data);
    return good;
}

int main(void) {
    static char line[10010];
    int q;
    if (!fgets(line, sizeof line, stdin)) return 0;
    q = atoi(line);
    for (int i = 0; i < q; i++) {
        if (!fgets(line, sizeof line, stdin)) line[0] = '\0';
        line[strcspn(line, "\r\n")] = '\0';
        puts(ok(line) ? "DA" : "NU");
    }
    return 0;
}

