#include <string.h>

typedef struct edge {
    int to, cost;
    struct edge *next;
} Edge;

typedef struct { long long d; int v; } Item;

/* min-heap of (distance, node) */
typedef struct { Item *a; int n; } MinHeap;

void hpush(MinHeap *h, Item x) {
    int k = h->n++;
    h->a[k] = x;
    while (k > 0 && h->a[(k - 1) / 2].d > h->a[k].d) {
        Item t = h->a[k]; h->a[k] = h->a[(k - 1) / 2]; h->a[(k - 1) / 2] = t;
        k = (k - 1) / 2;
    }
}

Item hpop(MinHeap *h) {
    Item top = h->a[0];
    h->a[0] = h->a[--h->n];
    int k = 0;
    for (;;) {
        int c = 2 * k + 1;
        if (c >= h->n) break;
        if (c + 1 < h->n && h->a[c + 1].d < h->a[c].d) c++;
        if (h->a[c].d >= h->a[k].d) break;
        Item t = h->a[k]; h->a[k] = h->a[c]; h->a[c] = t;
        k = c;
    }
    return top;
}

long long dijkstra(Edge **adj, int n, int m, int s, int t) {
    long long *d = (long long *)malloc((n + 1) * sizeof(long long));
    for (int i = 1; i <= n; i++) d[i] = -1;
    MinHeap h = {(Item *)malloc((2 * m + 2) * sizeof(Item)), 0};
    Item st = {0, s};
    d[s] = 0;
    hpush(&h, st);
    while (h.n) {
        Item x = hpop(&h);
        if (x.d > d[x.v]) continue;
        for (Edge *e = adj[x.v]; e; e = e->next) {
            long long nd = x.d + e->cost;
            if (d[e->to] < 0 || nd < d[e->to]) {
                d[e->to] = nd;
                Item y = {nd, e->to};
                hpush(&h, y);
            }
        }
    }
    long long r = d[t];
    free(d);
    free(h.a);
    return r;
}

void addEdge(Edge **adj, int a, int b, int c) {
    Edge *e = (Edge *)malloc(sizeof(Edge));
    e->to = b; e->cost = c; e->next = adj[a];
    adj[a] = e;
}

int main(void) {
    int n, m, s, p, d;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    Edge **adj = (Edge **)calloc(n + 1, sizeof(Edge *));
    for (int i = 0; i < m; i++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        addEdge(adj, a, b, c);
        addEdge(adj, b, a, c);
    }
    scanf("%d %d %d", &s, &p, &d);
    long long x = dijkstra(adj, n, m, s, p), y = dijkstra(adj, n, m, p, d);
    printf("%lld\n", x < 0 || y < 0 ? -1LL : x + y);
    for (int i = 1; i <= n; i++)
        while (adj[i]) { Edge *e = adj[i]->next; free(adj[i]); adj[i] = e; }
    free(adj);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    int v, cost;
    struct node *next;
} TNode, *ATNode;

typedef struct {
    int nn;
    ATNode *adl;
} TGraphL;

typedef struct {
    long long cost;
    int len;
    int *nodes;
} TDrum;

int *order, ordLen, *seen;

void dfs(TGraphL *g, int u) { /* iterative-free recursion is fine for the given sizes on a DAG */
    seen[u] = 1;
    for (ATNode p = g->adl[u]; p; p = p->next)
        if (!seen[p->v]) dfs(g, p->v);
    order[ordLen++] = u; /* finished: goes on the "stack" */
}

TDrum *Drum(TGraphL *g, int x, int y) {
    int n = g->nn;
    order = (int *)malloc(n * sizeof(int));
    seen = (int *)calloc(n + 1, sizeof(int));
    ordLen = 0;
    dfs(g, x); /* only the nodes reachable from x matter */
    long long *d = (long long *)malloc((n + 1) * sizeof(long long));
    int *pred = (int *)malloc((n + 1) * sizeof(int));
    char *reach = (char *)calloc(n + 1, 1);
    reach[x] = 1; d[x] = 0; pred[x] = 0;
    for (int i = ordLen - 1; i >= 0; i--) { /* topological order = reverse finishing order */
        int u = order[i];
        if (!reach[u]) continue;
        for (ATNode p = g->adl[u]; p; p = p->next)
            if (!reach[p->v] || d[u] + p->cost < d[p->v]) {
                reach[p->v] = 1;
                d[p->v] = d[u] + p->cost;
                pred[p->v] = u;
            }
    }
    TDrum *r = NULL;
    if (reach[y]) {
        r = (TDrum *)malloc(sizeof(TDrum));
        r->cost = d[y];
        r->len = 0;
        for (int v = y; v; v = pred[v]) r->len++;
        r->nodes = (int *)malloc(r->len * sizeof(int));
        int k = r->len;
        for (int v = y; v; v = pred[v]) r->nodes[--k] = v;
    }
    free(order); free(seen); free(d); free(pred); free(reach);
    return r;
}

int main(void) {
    TGraphL g;
    int m, x, y;
    if (scanf("%d %d", &g.nn, &m) != 2) return 0;
    g.adl = (ATNode *)calloc(g.nn + 1, sizeof(ATNode));
    for (int i = 0; i < m; i++) {
        ATNode e = (ATNode)malloc(sizeof(TNode));
        int a;
        scanf("%d %d %d", &a, &e->v, &e->cost);
        e->next = g.adl[a];
        g.adl[a] = e;
    }
    scanf("%d %d", &x, &y);
    TDrum *r = Drum(&g, x, y);
    if (!r) puts("NU");
    else {
        printf("%lld\n", r->cost);
        for (int i = 0; i < r->len; i++) printf("%d%c", r->nodes[i], i + 1 < r->len ? ' ' : '\n');
        free(r->nodes);
        free(r);
    }
    for (int i = 1; i <= g.nn; i++)
        while (g.adl[i]) { ATNode e = g.adl[i]->next; free(g.adl[i]); g.adl[i] = e; }
    free(g.adl);
    return 0;
}
